//
// Health-risk example — server side (CKKS)
//
// Scores one encrypted patient against the server's model. Never sees the
// secret key, the inputs, or the score.
//
// Record once, replay many: with cooperative auto-tagging the deserialize
// hooks tag the context, keys and input ciphertext by file. The first query
// records the circuit as a FHETCH trace; every later query finds the trace
// cached, so the server runs zero FHE ops — replay() notices that ct_x.bin
// changed on disk, loads the new patient onto the recorded addresses, and
// replays the same trace.
//
// Usage: ./health_risk_server <server_home> [--cpu] [niobium flags, e.g. --hollow]
//   Run from inside <server_home>: the trace cache is created in the working dir.
//   Reads  <server_home>/{cc,pk,mk,rk}.bin, model.txt, ct_x.bin
//   Writes <server_home>/ct_result.bin
//   --cpu  plain OpenFHE, no trace (the local correctness gate)

#include "openfhe.h"
#include "niobium/compiler.h"

#include <filesystem>

#include "ciphertext-ser.h"
#include "cryptocontext-ser.h"
#include "key/key-ser.h"
#include "scheme/ckksrns/ckksrns-ser.h"

#include "common.hpp"

using namespace lbcrypto;
using namespace health_risk;

// Ring-level comparison of two ciphertexts; returns the number of differing coefficients.
static size_t ring_diff(const Ciphertext<DCRTPoly>& a, const Ciphertext<DCRTPoly>& b) {
    const auto& ea = a->GetElements();
    const auto& eb = b->GetElements();
    if (ea.size() != eb.size()) return SIZE_MAX;
    size_t diffs = 0;
    for (size_t c = 0; c < ea.size(); ++c) {
        const auto& ta = ea[c].GetAllElements();
        const auto& tb = eb[c].GetAllElements();
        if (ta.size() != tb.size()) return SIZE_MAX;
        for (size_t t = 0; t < ta.size(); ++t) {
            const auto& va = ta[t].GetValues();
            const auto& vb = tb[t].GetValues();
            for (size_t i = 0; i < va.GetLength(); ++i) diffs += (va[i] != vb[i]);
        }
    }
    return diffs;
}

int main(int argc, char* argv[]) {
    bool cpu = false;
    for (int i = 1; i < argc; i++) cpu |= std::string(argv[i]) == "--cpu";

    if (!cpu) {
        niobium::compiler().init(argc, argv);
        // Must come before the crypto context is loaded (see docs/AUTO_FACADE.md).
        niobium::compiler().enable_auto_tagging();
        niobium::compiler().set_program_info(
            "health_risk_server", "1.0", "Framingham 2008 BMI risk score — FHETCH trace");
        niobium::compiler().set_build_info(__FILE__, __LINE__, __TIMESTAMP__);
        niobium::Compiler::CacheParameters params;
        params.push_back({"workload", "framingham_bmi"});
        niobium::compiler().cache_parameters(params);
    }

    std::string home;
    for (int i = 1; i < argc; i++)
        if (std::string(argv[i]).rfind("--", 0) != 0) { home = argv[i]; break; }
    if (home.empty()) {
        std::cerr << "Usage: " << argv[0] << " <server_home> [--cpu] [niobium flags]" << std::endl;
        return 2;
    }
    home = std::filesystem::absolute(home).string();

    // The server home must be safe to hand to an untrusted machine.
    if (std::filesystem::exists(home + "/sk.bin")) {
        std::cerr << "[REFUSED] a secret key is present in the server home (" << home
                  << "/sk.bin); the server must never hold it" << std::endl;
        return 1;
    }

    CryptoContext<DCRTPoly> cc;
    if (!Serial::DeserializeFromFile(home + "/cc.bin", cc, SerType::BINARY))
        throw std::runtime_error("Failed to load crypto context");
    {
        std::ifstream mk(home + "/mk.bin", std::ios::in | std::ios::binary);
        if (!mk.is_open() || !cc->DeserializeEvalMultKey(mk, SerType::BINARY))
            throw std::runtime_error("Failed to load eval mult key");
        std::ifstream rk(home + "/rk.bin", std::ios::in | std::ios::binary);
        if (!rk.is_open() || !cc->DeserializeEvalAutomorphismKey(rk, SerType::BINARY))
            throw std::runtime_error("Failed to load rotation keys");
    }
    const Model model = load_model(home + "/model.txt");

    const std::string in_path = home + "/ct_x.bin";
    Ciphertext<DCRTPoly> ct_x;
    if (!Serial::DeserializeFromFile(in_path, ct_x, SerType::BINARY))
        throw std::runtime_error("Failed to load input ciphertext");
    std::cout << "[server] received " << std::filesystem::file_size(in_path)
              << " bytes of ciphertext (ring " << cc->GetRingDimension() << ")" << std::endl;

    Ciphertext<DCRTPoly> ct_result;
    if (cpu) {
        ct_result = run_circuit(cc, model, ct_x);
    } else {
        Ciphertext<DCRTPoly> ct_openfhe;  // record-pass result, for the ring-level check
        if (!niobium::compiler().is_cache_valid()) {
            const bool hollow = niobium::compiler().is_hollow_mode();  // set by --hollow
            std::cout << "[server] no cached trace — recording ("
                      << (hollow ? "hollow" : "real math") << ")" << std::endl;
            niobium::compiler().enable_hollow_mode(hollow);
            niobium::compiler().start();
            auto out = run_circuit(cc, model, ct_x);
            niobium::compiler().probe("risk", out);
            niobium::compiler().stop();
            niobium::compiler().enable_hollow_mode(false);
            if (!hollow) ct_openfhe = out;  // a hollow record holds placeholder values
        } else {
            std::cout << "[server] cached trace found — replaying it for this patient" << std::endl;
        }

        if (!niobium::compiler().replay()) {
            std::cerr << "[ERROR] Replay failed" << std::endl;
            return 1;
        }
        if (!niobium::compiler().result(cc, "risk", ct_result)) {
            std::cerr << "[ERROR] Could not retrieve result" << std::endl;
            return 1;
        }
        if (ct_openfhe) {
            const size_t d = ring_diff(ct_openfhe, ct_result);
            std::cout << "[server] ring-level check, replay vs OpenFHE: "
                      << (d == 0 ? "bit-identical" : "MISMATCH (" + std::to_string(d) + " coefficients)")
                      << std::endl;
            if (d != 0) return 1;
        }
    }

    const std::string out_path = home + "/ct_result.bin";
    if (!Serial::SerializeToFile(out_path, ct_result, SerType::BINARY)) {
        std::cerr << "Error: Failed to serialize result ciphertext" << std::endl;
        return 1;
    }
    std::cout << "[server] returned " << std::filesystem::file_size(out_path)
              << " bytes, still encrypted" << std::endl;
    return 0;
}
